interface User { id: string; name: string; }

const db = new Map<string, User>([
  ['u_1', { id: 'u_1', name: 'Alice' }],
]);

function findUser(id: string): User;
function findUser(id: string, options: { includeDeleted: true }): User | null;
function findUser(id: string, options?: { includeDeleted: true }): User | null {
  const user = db.get(id) ?? null;
  return options?.includeDeleted ? user : (user as User);
}

const active = findUser('u_1'); // typé User
const maybeMissing = findUser('u_9', { includeDeleted: true }); // typé User | null

